import * as THREE from 'three';
import manifest from '../game/assetManifest.json';
import type { LayerFile } from '../game/levels/kit';

/** Asset manifest generated by scripts/build-assets.mjs. */
export type CharId = keyof typeof manifest.chars;
export interface AnimMeta { row: number; count: number; muzzle?: number[][] }
export interface PartMeta { name: string; ax: number; aw: number; ah: number; x: number; y: number }
export interface CharMeta {
  file: string; cellW: number; cellH: number; cols: number; rows: number; footX: number; figureH: number;
  anims: Record<string, AnimMeta>; parts: { file: string; w: number; h: number; list: PartMeta[]; joints: Record<string, number[]> }; portrait: string;
}
export interface CharAssets { meta: CharMeta; tex: THREE.Texture; parts: THREE.Texture; portraitUrl: string }
export interface Assets { layers: Record<LayerFile, THREE.Texture>; layerSize: Record<string, { w: number; h: number }>; chars: Record<CharId, CharAssets> }

const BASE = `${import.meta.env.BASE_URL}assets/`;
let cache: Assets | null = null;

function prep(t: THREE.Texture): THREE.Texture {
  t.colorSpace = THREE.SRGBColorSpace;
  t.minFilter = THREE.LinearMipmapLinearFilter; t.magFilter = THREE.LinearFilter;
  t.anisotropy = 4;
  return t;
}

/** Load all textures once (cached by the service worker for offline play). */
export async function loadAssets(onProgress: (p: number) => void): Promise<Assets> {
  if (cache) return cache;
  const loader = new THREE.TextureLoader();
  const jobs: Promise<void>[] = [];
  let done = 0, total = 0;
  const load = (url: string, set: (t: THREE.Texture) => void) => {
    total++;
    jobs.push(loader.loadAsync(url).then((t) => { set(prep(t)); onProgress(++done / total); }));
  };
  const layers = {} as Assets['layers'];
  for (const name of Object.keys(manifest.layers) as LayerFile[]) load(`${BASE}layers/${name}.webp`, (t) => { layers[name] = t; });
  const chars = {} as Assets['chars'];
  for (const [id, meta] of Object.entries(manifest.chars) as [CharId, CharMeta][]) {
    const entry = { meta, portraitUrl: `${BASE}chars/${meta.portrait}` } as CharAssets;
    chars[id] = entry;
    load(`${BASE}chars/${meta.file}`, (t) => { entry.tex = t; });
    load(`${BASE}chars/${meta.parts.file}`, (t) => { entry.parts = t; });
  }
  await Promise.all(jobs);
  cache = { layers, layerSize: manifest.layers, chars };
  return cache;
}
